<?php
namespace App\Reports\Standard;
use App\Reports\Queries\PurchaseReportQuery;use App\Services\Reports\Contracts\StandardReport;use App\Services\Reports\ReportResult;
final class PurchaseBySupplierReport extends AbstractStandardReport implements StandardReport{
 public function __construct(private readonly PurchaseReportQuery $purchase){}public function code():string{return 'PURCHASE_BY_SUPPLIER';}public function parameters():array{return array_merge($this->periodParameters(),$this->purchaseFilterParameters());}
 public function run(array $p):ReportResult{$m=PurchaseReportQuery::metricSelects();$rows=$this->purchase->postedInvoiceLines($p)->select('v.code as vendor_code','v.name as vendor_name','bu.code as business_unit')->selectRaw('COUNT(DISTINCT p.id) AS invoice_count')->selectRaw('SUM(l.quantity) AS quantity')->selectRaw('SUM('.$m['purchase_amount'].') AS purchase_amount')->selectRaw('CASE WHEN COUNT(DISTINCT p.id)>0 THEN SUM('.$m['purchase_amount'].')/COUNT(DISTINCT p.id) ELSE 0 END AS average_purchase')->selectRaw('MAX(p.document_date) AS last_purchase_date')->groupBy('v.code','v.name','bu.code')->orderByDesc('purchase_amount')->get()->all();return new ReportResult('Purchase by Supplier',[$this->col('vendor_code','Vendor'),$this->col('vendor_name','Name'),$this->col('business_unit','Business Unit'),$this->col('invoice_count','Invoices','number',0),$this->col('quantity','Qty','quantity',4),$this->col('purchase_amount','Purchase','money'),$this->col('average_purchase','Average Purchase','money'),$this->col('last_purchase_date','Last Purchase','date')],$rows,['Purchase'=>$this->moneySum($rows,'purchase_amount')],['quantity'=>$this->qtySum($rows,'quantity'),'purchase_amount'=>$this->moneySum($rows,'purchase_amount')]);}
}
